import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Storage Roadmap Enterprise Meets Community","description":"","frontmatter":{"title":"Ceph Storage Roadmap Enterprise Meets Community","date":"2026-07-09T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Ceph","会议纪要","存储集群","性能优化","社区动态"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Storage_Roadmap_Enterprise_Meets_Community.md","filePath":"posts/2026/Ceph_Storage_Roadmap_Enterprise_Meets_Community.md","lastUpdated":null}'),l={name:"posts/2026/Ceph_Storage_Roadmap_Enterprise_Meets_Community.md"};function i(n,t,s,g,h,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲由 IBM 产品经理 Federico 与社区技术负责人 Neha 联合主持，分别从企业商业路线图和社区开源路线图两个维度，介绍了 Ceph 当前的开发重点、已交付成果以及未来规划。这是疫情及 IBM 收购过渡期后，该系列演讲的重启之作。</p><h2 id="路线图历史背景" tabindex="-1">路线图历史背景 <a class="header-anchor" href="#路线图历史背景" aria-label="Permalink to &quot;路线图历史背景&quot;">​</a></h2><p>Federico 回顾了 Ceph 路线图透明度的历史：</p><ul><li>疫情期间，Sage 与 Federico 开创了&quot;State of the Cephalopod: Enterprise Meets Community&quot;系列演讲，同时涵盖企业路线图和社区路线图，在 Red Hat Summit 上发布</li><li>Sage 退休后，Josh 和 Federico 将该系列迁移至 Open Infra Summit，坚持举办三年</li><li>本次由 Neha 接替 Josh，在 Cephacon 上重启</li></ul><p><strong>路线图的定义</strong>：路线图是&quot;模糊的承诺&quot;而非保证。IBM 内部定义为：某功能在指定版本中有 70% 的概率交付，且集体上 70% 的计划功能会落地。&quot;标题功能&quot;（headliner）是必须完成的 5-10%，直接影响版本发布宣传。社区路线图则更接近&quot;背书&quot;——有人愿意做，PTL 认为可行，50% 的概率真正落地。</p><h2 id="ibm-企业路线图-中期-18-24-个月" tabindex="-1">IBM 企业路线图（中期，18-24 个月） <a class="header-anchor" href="#ibm-企业路线图-中期-18-24-个月" aria-label="Permalink to &quot;IBM 企业路线图（中期，18-24 个月）&quot;">​</a></h2><h3 id="已完成项目" tabindex="-1">已完成项目 <a class="header-anchor" href="#已完成项目" aria-label="Permalink to &quot;已完成项目&quot;">​</a></h3><ul><li><strong>Fast DC ARM 支持</strong>：ARM 架构适配</li><li><strong>万节点集群扩展</strong>（10,000 OSD）：第二阶段增强已完成</li><li><strong>FCM5 硬件支持</strong>：IBM 专属高速闪存存储，因 FCM 自带板载压缩，OSD 容量会动态变化，软件层面需专门适配</li></ul><h3 id="近期计划" tabindex="-1">近期计划 <a class="header-anchor" href="#近期计划" aria-label="Permalink to &quot;近期计划&quot;">​</a></h3><ul><li><strong>Direct Read</strong>：Erasure Coding 读性能增强，作为 Fast EC 的第二层优化，预计会 backport 到已发布版本</li><li><strong>Stretch + Erasure Coding</strong>：支持双站点拉伸集群配合 EC，解决仅复制池才能使用 stretch 模式的限制</li><li><strong>Pool Migration 工具</strong>：支持现有 pool 迁移到不同的 EC 几何配置，对于&quot;从小集群起步、逐步扩容&quot;的对象存储场景尤为重要（小集群通常选低冗余比 EC 方案，扩容后被旧编码方案锁定）</li><li><strong>Crimson + RGW Tech Preview</strong>：新一轮 Crimson 技术预览，聚焦 RGW 使用场景</li></ul><h3 id="远期规划" tabindex="-1">远期规划 <a class="header-anchor" href="#远期规划" aria-label="Permalink to &quot;远期规划&quot;">​</a></h3><ul><li><strong>Small Object Packing</strong>：将大量小对象打包存储，主要目的是减少 IO 开销（元数据 overhead），而非节省空间</li><li><strong>量子安全加密（Quantum-Safe Cryptography）</strong>：计划在 Ceph 11 或更晚版本中分阶段交付——外部传输（Cephx 协议）、静态加密（at-rest）、内部消息协议将分批获得量子安全支持</li><li><strong>Crimson + SeaStore 完整预览</strong>：持续保持在 2 年以上的交付目标，正在进行中；当前是参与影响设计的最佳时机，GA 之后再反馈就太晚了</li><li><strong>集群内部负载均衡</strong>：正在进行内部集群均衡优化；用户侧负载均衡因优先级问题暂时搁置，欢迎社区贡献</li></ul><h3 id="ai-相关方向" tabindex="-1">AI 相关方向 <a class="header-anchor" href="#ai-相关方向" aria-label="Permalink to &quot;AI 相关方向&quot;">​</a></h3><ul><li><strong>AI 参考架构</strong>：Kyle 和 Intel 的 Tushar 已发布博客（约 12 月/1 月），描述 KV Cache 场景下 Ceph 的使用方案</li><li><strong>S3 Vectors</strong>：由 RGW 团队在 Squid 9.2 版本中引入</li><li><strong>S3 over RDMA / GPU Direct</strong>：明年作为 Ceph AI 核心增强，支持 GPUDirect Storage 场景</li><li><strong>Smart Assist</strong>：基于 RAG 设计的智能配置助手，帮助用户理解集群配置含义并指向知识库文档；不执行代码，仅做解释和引导；计划提供 MCP Server 接口</li></ul><h2 id="社区路线图-neha-主讲" tabindex="-1">社区路线图（Neha 主讲） <a class="header-anchor" href="#社区路线图-neha-主讲" aria-label="Permalink to &quot;社区路线图（Neha 主讲）&quot;">​</a></h2><h3 id="tentacle-版本已交付功能" tabindex="-1">Tentacle 版本已交付功能 <a class="header-anchor" href="#tentacle-版本已交付功能" aria-label="Permalink to &quot;Tentacle 版本已交付功能&quot;">​</a></h3><p><strong>RADOS / Erasure Coding</strong></p><ul><li>Fast EC 正式可用，带来 TCO 改善和性能提升，覆盖块、文件、对象存储</li><li>对块存储和文件存储具有重大差异化价值</li></ul><p><strong>BlueStore</strong></p><ul><li>内联压缩能力增强：更可调（tunable）、更高效</li></ul><p><strong>RGW（Rados Gateway）</strong></p><ul><li>新增 AWS IAM Accounts 支持，提供细粒度访问控制和自服务 API</li></ul><p><strong>CephFS / MDS</strong></p><ul><li>支持大小写不敏感目录树，改善与 NFS 和 Samba 的互操作性</li></ul><p><strong>RBD</strong></p><ul><li>Live Migration（在线迁移）</li><li>RBD Mirroring 期间支持 Namespace Remapping</li></ul><p><strong>NVMe-oF</strong></p><ul><li>NVMe-oF Gateway 高可用支持正式 GA（Tentacle 版本）</li></ul><p><strong>Dashboard</strong></p><ul><li>更多用户和客户开始采用 Dashboard</li><li>SMB、NVMe 等协议的 Day 1/Day 2 工作流已加入 Dashboard</li><li>IAM 管理功能上线</li></ul><p><strong>Cephadm</strong></p><ul><li>稳定性提升，特别是大规模场景</li><li>新增证书管理（Certificate Management）能力</li></ul><p><strong>Crimson / SeaStore</strong></p><ul><li>Tentacle 中完成技术预览</li><li>已有 Cephadm 支持：使用单一 flag 即可部署 Crimson 集群</li><li>专属 Slack 频道持续收集社区反馈，参与者来自全球各地</li></ul><h3 id="未来版本计划" tabindex="-1">未来版本计划 <a class="header-anchor" href="#未来版本计划" aria-label="Permalink to &quot;未来版本计划&quot;">​</a></h3><p><strong>RADOS 进一步增强</strong></p><ul><li><strong>Direct Read for EC</strong>：提升 EC 读性能</li><li><strong>OMAP in EC</strong>：EC 将支持 OMAP，使 EC 在功能上完全对标复制池，未来可构建全 EC 集群（此前版本不可能实现）</li><li><strong>Pool Migration 工具</strong>：支持从复制池或旧 EC 迁移到 Fast EC 以及 Fast EC + Direct Read 配置</li></ul><p><strong>Ceph Manager 健壮性</strong></p><ul><li>Manager 模块数量持续增加，新增缓存层以提升核心稳定性，确保在大量模块并行工作时不影响集群状态展示</li></ul><p><strong>Stretch Cluster + EC 支持</strong></p><ul><li>当前 stretch 模式仅支持复制池（双站点 + 第三站点仲裁 Monitor）</li><li>规划中：为 stretch 集群添加 EC 支持，从而降低成本、提升灵活性，支持 2AZ 或 3AZ 配置，用户可自选复制或 EC</li></ul><p><strong>Small Object Packing</strong></p><ul><li>针对大量 S3 小对象场景，减少 listing 和元数据开销</li><li>目前处于设计阶段，预计未来版本落地</li></ul><p><strong>Crimson + SeaStore 下一步</strong></p><ul><li>下一版本将 Tech Preview Crimson + SeaStore 支持块、对象、文件存储的完整组合（当前仅有 BlueStore alien store 的块存储预览）</li></ul><p><strong>升级体验改进</strong></p><ul><li>Cephadm 持续优化大规模集群下的无缝升级流程</li></ul><h2 id="关键结论与后续行动" tabindex="-1">关键结论与后续行动 <a class="header-anchor" href="#关键结论与后续行动" aria-label="Permalink to &quot;关键结论与后续行动&quot;">​</a></h2><ol><li><strong>Crimson 正在积极征集反馈</strong>：当前是影响设计方向的最佳窗口，GA 后再反馈为时已晚；可加入专属 Slack 频道参与讨论</li><li><strong>Fast EC 已可用</strong>：Tentacle 版本中可直接使用，建议评估对现有业务的适用性</li><li><strong>Pool Migration 需求明确</strong>：面向对象存储用户，解决小集群起步后 EC 方案锁定问题</li><li><strong>AI 集成方向清晰</strong>：S3 Vectors、GPU Direct、RAG 智能助手均已在路线图中，AI 场景下 Ceph 的价值正在增强</li><li><strong>路线图透明度恢复</strong>：IBM 将恢复每年至少一次的内部路线图公开，社区可持续了解企业优先级</li></ol>',50)])])}const c=e(l,[["render",i]]);export{d as __pageData,c as default};
